707		Let $G$ be an LCS game over $\Z_d$ with vertex set $V$, edge set $E$, and constraints given by  $H:V\times E \to \Z_d$ and $l: V\to \Z_d$. Let $\G$ be the solution group of $G$. Suppose that:
708		\begin{enumerate}[(i)]
709			\item \label{assumption:bounded-degree}
710			 $\abs E \leq \Delta$, $\abs V \leq \Delta$, and
711			 each equation has at most $\Delta$ variables with multiplicity, i.e.\ \mbox{$\forall v:\sum_e\abs{H(v,e)} \leq \Delta$},
712			\item \label{assumption:small-pictures}there is a canonical form $\can$ such that\footnote{We'll also need a technical assumption that for all $x\in \G$, $\can(Jx) = J\can(x)$ or $\can(Jx) = J^{1-d}\can(x)$.} 
713			every equation of the form  $\can(e)e\1 = 1$ for $e\in E$ or $\can(g)\can(gh)\1\can(h) = 1$ for $g,h\in \G$ is witnessed by a $\G$-picture in which 
714			 each variable is used at most $\Delta$ times
715			 and 
716			 each relation is used at most $\Delta$ times,
717			\item \label{assumption:w-p-irreps}
718			 $\G$ group-tests $\tau: \G \to U(\C^{d^n}) $ in the sense of Definition \ref{definition:group-test}.
719	% 		\item \label{assumption:pauli-in-image}The image of $\tau$ contains an isomorphic copy of the Pauli group $\m P_d^{\otimes n}$. 
720		\end{enumerate}
721		Then $G$ self-tests the strategy $\tilde A_e^{(v)} = \tau(e), \tilde B_e = \bar{\tau(e)}, \ket\psi = \ket{\r{EPR}_{d^n}}$
722		with perfect completeness and $O(d^2\Delta^{10}\e)$-robustness.
